#include <iostream>

class Shape {
public:
    virtual ~Shape() = default;
    virtual void draw() const { std::cout << "shape\n"; }
    virtual double size() const { return 0; }
};
class Circle : public Shape {
public:
    explicit Circle(double r) : r_(r) {}
    void draw() const override { std::cout << "circle " << r_ << '\n'; }
    double size() const override { return r_; }     // virtual: no cast needed.
    double radius() const { return r_; }
private:
    double r_;
};

void describe_sliced(Shape s)       { s.draw(); }   // copies Shape part: "shape".
void describe(const Shape& s)       { s.draw(); }   // no slicing: "circle 2".

void show_radius(const Shape& s) {
    if (auto c = dynamic_cast<const Circle*>(&s)) std::cout << c->radius() << '\n';
    else std::cout << "not a circle\n";           // checked: safe for any shape.
}

int main() {
    Circle c{2.0};
    describe_sliced(c);   // shape.
    describe(c);          // circle 2.
    show_radius(c);       // 2.
}
```

